BEGIN;
CREATE SCHEMA plan_test;
CREATE FUNCTION plan_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;
CREATE FUNCTION plan_test.denied(statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN;END;RAISE EXCEPTION 'Expected rejection: %',statement;END $$;
GRANT USAGE ON SCHEMA plan_test TO authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA plan_test TO authenticated;
INSERT INTO auth.users(id,email) SELECT ('26000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'plan-'||n||'@example.invalid' FROM generate_series(1,6)n;
INSERT INTO public.companies(id,nome,created_by) VALUES('16000000-0000-4000-8000-000000000001','Preventive fixture','26000000-0000-4000-8000-000000000001'),('16000000-0000-4000-8000-000000000002','Other preventive fixture','26000000-0000-4000-8000-000000000001');
INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) SELECT '16000000-0000-4000-8000-000000000001',('26000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'auditor',(ARRAY['admin_empresa','analista_transporte','supervisor','operador_logistico','motorista','cliente'])[n],'26000000-0000-4000-8000-000000000001' FROM generate_series(1,6)n;
INSERT INTO public.veiculos(id,company_id,placa,tipo,marca_modelo,km_atual) VALUES('36000000-0000-4000-8000-000000000001','16000000-0000-4000-8000-000000000001','PLAN001','caminhao','Fixture 1',1000),('36000000-0000-4000-8000-000000000002','16000000-0000-4000-8000-000000000001','PLAN002','caminhao','Fixture 2',5000);
INSERT INTO public.maintenance_partners(id,company_id,razao_social,created_by) VALUES('46000000-0000-4000-8000-000000000001','16000000-0000-4000-8000-000000000001','Preventive workshop','26000000-0000-4000-8000-000000000001');
CREATE FUNCTION plan_test.act(action text,payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER AS $$ SELECT public.maintenance_plan_command('16000000-0000-4000-8000-000000000001',action,payload); $$;
GRANT EXECUTE ON FUNCTION plan_test.act(text,jsonb) TO authenticated;
SET LOCAL ROLE authenticated;SELECT set_config('request.jwt.claim.sub','26000000-0000-4000-8000-000000000001',true);
SELECT set_config('plan_test.id',plan_test.act('save',jsonb_build_object('nome','Troca de óleo','categoria_veiculo','caminhao','intervalo_km',1000,'intervalo_dias',30,'ultima_execucao_data',current_date,'ativo',true))->>'id',true);
SELECT plan_test.assert(jsonb_array_length(plan_test.act('context')->'plans')=1,'context lists configured plans');
SELECT plan_test.assert((SELECT count(*)=2 FROM public.maintenance_plan_vehicles WHERE company_id='16000000-0000-4000-8000-000000000001'),'category expands separately');
SELECT plan_test.assert((SELECT (a->>'proxima_km')::numeric=2000 FROM jsonb_array_elements(plan_test.act('alerts')->'rows') a WHERE a->>'placa'='PLAN001'),'first vehicle odometer baseline');
SELECT plan_test.assert((SELECT (a->>'proxima_km')::numeric=6000 FROM jsonb_array_elements(plan_test.act('alerts')->'rows') a WHERE a->>'placa'='PLAN002'),'second vehicle independent baseline');
SELECT plan_test.denied($q$SELECT public.maintenance_plan_command('16000000-0000-4000-8000-000000000002','context','{}')$q$);
SELECT plan_test.denied($q$SELECT plan_test.act('save','{"nome":"Bad","categoria_veiculo":"caminhao","intervalo_km":0,"ultima_execucao_data":"2020-01-01"}')$q$);
RESET ROLE;UPDATE public.veiculos SET km_atual=1500 WHERE id='36000000-0000-4000-8000-000000000001';
SELECT maintenance_private.process_preventive_alerts();SELECT maintenance_private.process_preventive_alerts();
SELECT plan_test.assert((SELECT count(*)=2 FROM public.maintenance_preventive_notifications WHERE company_id='16000000-0000-4000-8000-000000000001' AND resolved_at IS NULL),'only analyst/operator notified once');
SET LOCAL ROLE authenticated;SELECT set_config('request.jwt.claim.sub','26000000-0000-4000-8000-000000000004',true);
SELECT plan_test.assert(plan_test.act('notifications')->>'unread'='1','operator notified');
SELECT plan_test.denied($q$SELECT plan_test.act('save','{"nome":"Denied"}')$q$);
SELECT plan_test.denied($q$SELECT plan_test.act('settings','{"dias":7,"km":500,"version":1}')$q$);
SELECT plan_test.act('notification_read',jsonb_build_object('id',(SELECT id FROM public.maintenance_preventive_notifications WHERE company_id='16000000-0000-4000-8000-000000000001')));
RESET ROLE;SELECT maintenance_private.process_preventive_alerts();
SET LOCAL ROLE authenticated;
SELECT plan_test.assert(plan_test.act('notifications')->>'unread'='0','repeated daily run preserves read marker');
SELECT set_config('plan_test.vehicle',(SELECT id::text FROM public.maintenance_plan_vehicles WHERE vehicle_id='36000000-0000-4000-8000-000000000001'),true);
SELECT set_config('plan_test.order',plan_test.act('create_order',jsonb_build_object('plan_vehicle_id',current_setting('plan_test.vehicle'),'vehicle_id','36000000-0000-4000-8000-000000000001','partner_id','46000000-0000-4000-8000-000000000001','tipo','corretiva','prioridade','media','descricao_problema','Troca de óleo preventiva','km_abertura',1500))->>'id',true);
SELECT plan_test.assert((SELECT tipo='preventiva' FROM public.maintenance_orders WHERE id=current_setting('plan_test.order')::uuid),'preventive type enforced');
SELECT plan_test.assert(plan_test.act('create_order',jsonb_build_object('plan_vehicle_id',current_setting('plan_test.vehicle'),'vehicle_id','36000000-0000-4000-8000-000000000001'))->>'id'=current_setting('plan_test.order'),'duplicate create returns existing OS');
SELECT set_config('request.jwt.claim.sub','26000000-0000-4000-8000-000000000005',true);SELECT plan_test.denied($q$SELECT plan_test.act('alerts')$q$);
SELECT set_config('request.jwt.claim.sub','26000000-0000-4000-8000-000000000006',true);SELECT plan_test.denied($q$SELECT plan_test.act('context')$q$);
RESET ROLE;SELECT set_config('request.jwt.claim.sub','26000000-0000-4000-8000-000000000001',true);
UPDATE public.veiculos SET km_atual=2000 WHERE id='36000000-0000-4000-8000-000000000001';SELECT maintenance_private.process_preventive_alerts();
SELECT plan_test.assert((SELECT bool_and(estado='vencida' AND read_at IS NULL) FROM public.maintenance_preventive_notifications WHERE company_id='16000000-0000-4000-8000-000000000001' AND resolved_at IS NULL),'state crossing triggers new notice');
CREATE FUNCTION plan_test.os(action text,payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER AS $$ SELECT public.maintenance_order_command('16000000-0000-4000-8000-000000000001',action,payload||jsonb_build_object('id',current_setting('plan_test.order'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('plan_test.order')::uuid)));$$;
GRANT EXECUTE ON FUNCTION plan_test.os(text,jsonb) TO authenticated;
SET LOCAL ROLE authenticated;
SELECT plan_test.os('arrival','{"km":2000,"observacao":"Chegada preventiva"}');
SELECT plan_test.os('item_save','{"tipo":"servico","descricao":"Troca de óleo contratada","quantidade":1,"valor_unitario":0}');
SELECT plan_test.os('budget','{"decisao":"aprovado","observacao":"Contrato cobre o serviço"}');
SELECT plan_test.os('transition','{"status":"em_execucao","observacao":"Iniciado"}');
SELECT plan_test.os('transition','{"status":"concluido","observacao":"Concluído","servicos_executados":"Troca de óleo e filtro","valor_final":0}');
SELECT plan_test.os('departure','{"km":2000,"observacao":"Veículo retirado"}');
SELECT plan_test.os('transition','{"status":"encerrada","observacao":"Preventiva encerrada"}');
RESET ROLE;
SELECT plan_test.assert((SELECT ultima_execucao_km=2000 AND cycle=2 FROM public.maintenance_plan_vehicles WHERE id=current_setting('plan_test.vehicle')::uuid),'closure updates execution');
SELECT plan_test.assert((SELECT ultima_execucao_km=5000 AND cycle=1 FROM public.maintenance_plan_vehicles WHERE vehicle_id='36000000-0000-4000-8000-000000000002'),'closure does not reset category peers');
SELECT plan_test.assert((SELECT count(*)=0 FROM public.maintenance_preventive_notifications WHERE company_id='16000000-0000-4000-8000-000000000001' AND resolved_at IS NULL),'closure resolves notices');
SET LOCAL ROLE authenticated;
SELECT plan_test.assert((SELECT (a->>'proxima_km')::numeric=3000 FROM jsonb_array_elements(plan_test.act('alerts')->'rows') a WHERE a->>'placa'='PLAN001'),'recalculated next KM');
SELECT plan_test.assert(NOT has_table_privilege('authenticated','public.maintenance_plans','UPDATE'),'plan edits require checked command');
SELECT plan_test.assert(NOT has_function_privilege('anon','public.maintenance_plan_command(uuid,text,jsonb)','EXECUTE'),'anonymous denied');
SELECT plan_test.denied($q$SELECT maintenance_private.process_preventive_alerts()$q$);

SELECT set_config('plan_test.order',plan_test.act('create_order',jsonb_build_object('plan_vehicle_id',current_setting('plan_test.vehicle'),'vehicle_id','36000000-0000-4000-8000-000000000001','partner_id','46000000-0000-4000-8000-000000000001','prioridade','media','descricao_problema','Segunda OS preventiva','km_abertura',2000))->>'id',true);
SELECT plan_test.os('transition','{"status":"cancelada","observacao":"Cancelada por teste"}');
SELECT plan_test.assert((SELECT cycle=2 FROM public.maintenance_plan_vehicles WHERE id=current_setting('plan_test.vehicle')::uuid),'cancellation does not execute plan');
SELECT plan_test.act('save',jsonb_build_object('nome','Licenciamento','vehicle_id','36000000-0000-4000-8000-000000000002','intervalo_dias',7,'ultima_execucao_data',current_date-10,'ultima_execucao_km',5000,'ativo',true));
SELECT plan_test.assert((SELECT a->>'estado'='vencida' AND a->>'proxima_km' IS NULL FROM jsonb_array_elements(plan_test.act('alerts')->'rows') a WHERE a->>'nome'='Licenciamento'),'date-only plan overdue without KM');
SELECT plan_test.act('settings',jsonb_build_object('version',(SELECT version FROM public.maintenance_settings WHERE company_id='16000000-0000-4000-8000-000000000001'),'dias',10,'km',750));
SELECT plan_test.assert((SELECT limite_aprovacao_supervisor=5000 AND intervalo_cobranca_horas=24 FROM public.maintenance_settings WHERE company_id='16000000-0000-4000-8000-000000000001'),'preventive settings preserve prior budget and communication settings');
RESET ROLE;ROLLBACK;
